// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes32 role, address caller, address other) public {
        vm.assume(caller != address(0));
        vm.assume(other != caller);

        vm.prank(caller);
        bool ok;
        try c.renounceRole(role, other) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: for any caller, renouncing a role on behalf of ANY account other
        // than the caller always reverts (and never changes membership).
        assertTrue(!ok);
    }
}
